"""Strict portable JSON Conversation serialization."""

from __future__ import annotations

import json
from typing import TYPE_CHECKING, NoReturn

from devtools.agents.conversation.conversation import ConversationId
from devtools.agents.conversation.message import (
    ConversationMessageRole,
    MessageId,
)
from devtools.core.time import TimeError, Timestamp
from devtools.models.interaction import ConversationRef, InteractionSource
from devtools.persistence._snapshot import (
    _MessageSnapshot,
    capture_conversation,
    restore_conversation,
    snapshot_from_values,
)
from devtools.persistence.errors import (
    PersistenceConflictError,
    PersistenceFormatError,
    PersistenceVersionError,
)

if TYPE_CHECKING:
    from devtools.agents.conversation.conversation import Conversation


_SCHEMA_VERSION = 1


def encode_conversation_json(conversation: Conversation) -> str:
    """Encode one Conversation semantic snapshot as deterministic strict JSON text."""
    snapshot = capture_conversation(conversation)
    value: dict[str, object] = {
        "schema_version": _SCHEMA_VERSION,
        "session": {
            "id": str(snapshot.id),
            "created_at": snapshot.created_at.isoformat(),
        },
        "history": [
            {
                "id": str(message.id),
                "created_at": message.created_at.isoformat(),
                "content": message.content,
                "role": message.role.value,
                "source": str(message.source),
            }
            for message in snapshot.messages
        ],
        "conversations": [
            {
                "source": str(conversation.source),
                "value": conversation.value,
            }
            for conversation in snapshot.conversations
        ],
    }
    serialized = json.dumps(
        value,
        ensure_ascii=False,
        indent=2,
        sort_keys=True,
        allow_nan=False,
    )
    return f"{serialized}\n"


def decode_conversation_json(text: str) -> Conversation:
    """Decode one strict JSON Conversation semantic snapshot."""
    try:
        parsed: object = json.loads(
            text,
            object_pairs_hook=_reject_duplicate_keys,
            parse_constant=_reject_nonstandard_constant,
        )
    except PersistenceFormatError:
        raise
    except (json.JSONDecodeError, ValueError) as error:
        msg = "Invalid Conversation JSON representation."
        raise PersistenceFormatError(msg) from error

    try:
        root = _require_object(parsed, "root")
        _require_fields(
            root,
            {"schema_version", "session", "history", "conversations"},
            "root",
        )
        _validate_version(root["schema_version"])
        session_value = _require_object(root["session"], "session")
        _require_fields(session_value, {"id", "created_at"}, "session")
        conversation_id = ConversationId.parse(
            _require_string(session_value["id"], "session.id"),
        )
        created_at = Timestamp.from_isoformat(
            _require_string(session_value["created_at"], "session.created_at"),
        )
        history_value = _require_list(root["history"], "history")
        messages = tuple(
            _decode_message(value, index) for index, value in enumerate(history_value)
        )
        conversations_value = _require_list(root["conversations"], "conversations")
        conversations = tuple(
            _decode_conversation(value, index)
            for index, value in enumerate(conversations_value)
        )
        _validate_conversation_sources(conversations)
        snapshot = snapshot_from_values(
            conversation_id=conversation_id,
            created_at=created_at,
            messages=messages,
            conversations=conversations,
        )
        return restore_conversation(snapshot)
    except (PersistenceConflictError, PersistenceFormatError, PersistenceVersionError):
        raise
    except (TimeError, TypeError, ValueError) as error:
        msg = "Invalid Conversation JSON semantic value."
        raise PersistenceFormatError(msg) from error


def _decode_message(value: object, index: int) -> _MessageSnapshot:
    """Decode one History occurrence."""
    item = _require_object(value, f"history[{index}]")
    _require_fields(
        item,
        {"id", "created_at", "content", "role", "source"},
        f"history[{index}]",
    )
    return _MessageSnapshot(
        id=MessageId.parse(_require_string(item["id"], f"history[{index}].id")),
        created_at=Timestamp.from_isoformat(
            _require_string(item["created_at"], f"history[{index}].created_at"),
        ),
        content=_require_string(item["content"], f"history[{index}].content"),
        role=ConversationMessageRole(
            _require_string(item["role"], f"history[{index}].role"),
        ),
        source=InteractionSource(
            _require_string(item["source"], f"history[{index}].source"),
        ),
    )


def _decode_conversation(value: object, index: int) -> ConversationRef:
    """Decode one current opaque conversation reference."""
    item = _require_object(value, f"conversations[{index}]")
    _require_fields(item, {"source", "value"}, f"conversations[{index}]")
    return ConversationRef(
        InteractionSource(
            _require_string(item["source"], f"conversations[{index}].source"),
        ),
        _require_string(item["value"], f"conversations[{index}].value"),
    )


def _require_object(value: object, field: str) -> dict[str, object]:
    """Return an object-shaped JSON value."""
    if not isinstance(value, dict):
        msg = f"Conversation JSON field {field} must be an object."
        raise PersistenceFormatError(msg)
    return value


def _require_list(value: object, field: str) -> list[object]:
    """Return a list-shaped JSON value."""
    if not isinstance(value, list):
        msg = f"Conversation JSON field {field} must be an array."
        raise PersistenceFormatError(msg)
    return value


def _require_string(value: object, field: str) -> str:
    """Return a string-shaped JSON value."""
    if not isinstance(value, str):
        msg = f"Conversation JSON field {field} must be a string."
        raise PersistenceFormatError(msg)
    return value


def _require_fields(value: dict[str, object], expected: set[str], field: str) -> None:
    """Require an exact object field set."""
    if set(value) != expected:
        msg = f"Conversation JSON field {field} has an unsupported field set."
        raise PersistenceFormatError(msg)


def _validate_version(value: object) -> None:
    """Validate the one supported JSON schema version."""
    if type(value) is not int:
        msg = "Conversation JSON schema_version must be an integer."
        raise PersistenceFormatError(msg)
    if value != _SCHEMA_VERSION:
        msg = f"Unsupported Conversation JSON schema version: {value}."
        raise PersistenceVersionError(msg)


def _reject_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
    """Reject duplicate object keys instead of silently collapsing them."""
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            msg = f"Duplicate Conversation JSON object key: {key}."
            raise PersistenceFormatError(msg)
        value[key] = item
    return value


def _reject_nonstandard_constant(value: str) -> NoReturn:
    """Reject JSON constants outside the standard JSON grammar."""
    msg = f"Invalid Conversation JSON constant: {value}."
    raise PersistenceFormatError(msg)


def _validate_conversation_sources(conversations: tuple[ConversationRef, ...]) -> None:
    """Reject ambiguous current continuation sources."""
    sources = {conversation.source for conversation in conversations}
    if len(sources) != len(conversations):
        msg = "Conversation JSON cannot contain multiple conversations for one source."
        raise PersistenceFormatError(msg)

# Copyright (c) 2026
"""Immutable terminal Evidence for interaction-attempt lifecycle facts."""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

from devtools.core.identity import Identity
from devtools.core.time import Timestamp

if TYPE_CHECKING:
    from devtools.execution.interaction_attempt import (
        InteractionAttemptId,
        InteractionAttemptOutcome,
    )


@dataclass(frozen=True, slots=True)
class EvidenceId:
    """Identify one immutable Evidence record."""

    value: Identity

    @classmethod
    def new(cls) -> EvidenceId:
        """Generate an Evidence identity."""
        return cls(Identity.new())

    @classmethod
    def parse(cls, value: str) -> EvidenceId:
        """Parse UUID text as an Evidence identity."""
        return cls(Identity.parse(value))

    def __str__(self) -> str:
        """Return canonical UUID text."""
        return str(self.value)


@dataclass(frozen=True, slots=True, kw_only=True)
class InteractionAttemptTerminalEvidence:
    """Record one immutable observation of a terminal interaction attempt."""

    id: EvidenceId
    attempt_id: InteractionAttemptId
    occurred_at: Timestamp
    observed_at: Timestamp
    outcome: InteractionAttemptOutcome

    @classmethod
    def new(
        cls,
        *,
        attempt_id: InteractionAttemptId,
        occurred_at: Timestamp,
        outcome: InteractionAttemptOutcome,
    ) -> InteractionAttemptTerminalEvidence:
        """Create a terminal record with a fresh observation identity."""
        return cls(
            id=EvidenceId.new(),
            attempt_id=attempt_id,
            occurred_at=occurred_at,
            observed_at=Timestamp.now(),
            outcome=outcome,
        )

# Copyright (c) 2026
"""Normalized SQLite current-snapshot Conversation store."""

from __future__ import annotations

import sqlite3
from typing import TYPE_CHECKING

from devtools.agents.conversation.message import (
    ConversationMessageRole,
    MessageId,
)
from devtools.core.time import TimeError, Timestamp
from devtools.models.interaction import ConversationRef, InteractionSource
from devtools.persistence._snapshot import (
    _ConversationSnapshot,
    _MessageSnapshot,
    capture_conversation,
    restore_conversation,
)
from devtools.persistence.errors import (
    PersistenceConflictError,
    PersistenceFormatError,
    PersistenceVersionError,
)

if TYPE_CHECKING:
    from devtools.agents.conversation.conversation import Conversation, ConversationId
    from devtools.core.paths import ResolvedPath


_SCHEMA_VERSION = 1
_TABLES = {"sessions", "messages", "session_messages", "conversations"}
_REQUIRED_COLUMNS = {
    "sessions": {"session_id", "created_at"},
    "messages": {"message_id", "created_at", "content", "role", "source"},
    "session_messages": {"session_id", "position", "message_id"},
    "conversations": {"session_id", "source", "value"},
}
_SCHEMA = """
CREATE TABLE sessions (
    session_id TEXT PRIMARY KEY NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE messages (
    message_id TEXT PRIMARY KEY NOT NULL,
    created_at TEXT NOT NULL,
    content TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'system')),
    source TEXT NOT NULL
);
CREATE TABLE session_messages (
    session_id TEXT NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 0),
    message_id TEXT NOT NULL,
    PRIMARY KEY (session_id, position),
    FOREIGN KEY (session_id) REFERENCES sessions(session_id) ON DELETE CASCADE,
    FOREIGN KEY (message_id) REFERENCES messages(message_id)
);
CREATE TABLE conversations (
    session_id TEXT NOT NULL,
    source TEXT NOT NULL,
    value TEXT NOT NULL,
    PRIMARY KEY (session_id, source),
    FOREIGN KEY (session_id) REFERENCES sessions(session_id) ON DELETE CASCADE
);
CREATE INDEX idx_sessions_created_at ON sessions(created_at);
CREATE INDEX idx_session_messages_message_id ON session_messages(message_id);
CREATE INDEX idx_conversations_source ON conversations(source);
"""


class SqliteConversationStore:
    """Persist current Conversation snapshots in a normalized SQLite database."""

    __slots__ = ("_database",)

    def __init__(self, *, database: ResolvedPath) -> None:
        """Configure a store for one absolute SQLite database path."""
        self._database = database

    def save(self, conversation: Conversation) -> None:
        """Atomically replace the persisted semantic snapshot for one Conversation."""
        snapshot = capture_conversation(conversation)
        connection = self._open_connection()
        try:
            with connection:
                self._save_snapshot(connection, snapshot)
        finally:
            connection.close()

    def load(self, conversation_id: ConversationId) -> Conversation | None:
        """Load one persisted Conversation object, if present."""
        connection = self._open_connection()
        try:
            row = connection.execute(
                "SELECT created_at FROM sessions WHERE session_id = ?",
                (str(conversation_id),),
            ).fetchone()
            if row is None:
                return None
            try:
                snapshot = _ConversationSnapshot(
                    id=conversation_id,
                    created_at=Timestamp.from_isoformat(row[0]),
                    messages=self._load_messages(connection, conversation_id),
                    conversations=self._load_conversations(connection, conversation_id),
                )
                return restore_conversation(snapshot)
            except (TimeError, TypeError, ValueError) as error:
                msg = (
                    "Invalid persisted Conversation state for ConversationId "
                    f"{conversation_id}."
                )
                raise PersistenceFormatError(msg) from error
        finally:
            connection.close()

    def _open_connection(self) -> sqlite3.Connection:
        """Open, configure, and validate one short-lived SQLite connection."""
        connection = sqlite3.connect(str(self._database))
        try:
            connection.execute("PRAGMA foreign_keys = ON")
            self._ensure_schema(connection)
        except Exception:
            connection.close()
            raise
        else:
            return connection

    def _ensure_schema(self, connection: sqlite3.Connection) -> None:
        """Initialize an empty database or validate the supported schema."""
        version = connection.execute("PRAGMA user_version").fetchone()[0]
        if version == 0:
            tables = _user_tables(connection)
            if tables:
                msg = "SQLite database is not an empty persistence database."
                raise PersistenceFormatError(msg)
            with connection:
                connection.executescript(_SCHEMA)
                connection.execute(f"PRAGMA user_version = {_SCHEMA_VERSION}")
            return
        if version != _SCHEMA_VERSION:
            msg = f"Unsupported SQLite persistence schema version: {version}."
            raise PersistenceVersionError(msg)
        if not _TABLES.issubset(_user_tables(connection)):
            msg = "SQLite persistence schema is missing required tables."
            raise PersistenceFormatError(msg)
        _validate_required_columns(connection)

    def _save_snapshot(
        self,
        connection: sqlite3.Connection,
        snapshot: _ConversationSnapshot,
    ) -> None:
        """Save one validated snapshot inside the caller's transaction."""
        conversation_id = str(snapshot.id)
        created_at = snapshot.created_at.isoformat()
        existing = connection.execute(
            "SELECT created_at FROM sessions WHERE session_id = ?",
            (conversation_id,),
        ).fetchone()
        if existing is None:
            connection.execute(
                "INSERT INTO sessions(session_id, created_at) VALUES (?, ?)",
                (conversation_id, created_at),
            )
        elif existing[0] != created_at:
            msg = f"Conflicting created_at for ConversationId {snapshot.id}."
            raise PersistenceConflictError(msg)

        for message in snapshot.messages:
            self._save_message(connection, message)

        connection.execute(
            "DELETE FROM session_messages WHERE session_id = ?",
            (conversation_id,),
        )
        connection.execute(
            "DELETE FROM conversations WHERE session_id = ?",
            (conversation_id,),
        )
        connection.executemany(
            "INSERT INTO session_messages(session_id, position, message_id) "
            "VALUES (?, ?, ?)",
            [
                (conversation_id, position, str(message.id))
                for position, message in enumerate(snapshot.messages)
            ],
        )
        connection.executemany(
            "INSERT INTO conversations(session_id, source, value) VALUES (?, ?, ?)",
            [
                (conversation_id, str(conversation.source), conversation.value)
                for conversation in snapshot.conversations
            ],
        )

    def _save_message(
        self,
        connection: sqlite3.Connection,
        message: _MessageSnapshot,
    ) -> None:
        """Insert one immutable ConversationMessage or validate its existing row."""
        message_id = str(message.id)
        values = (
            message.created_at.isoformat(),
            message.content,
            message.role.value,
            str(message.source),
        )
        existing = connection.execute(
            "SELECT created_at, content, role, source "
            "FROM messages WHERE message_id = ?",
            (message_id,),
        ).fetchone()
        if existing is None:
            connection.execute(
                "INSERT INTO messages(message_id, created_at, content, role, source) "
                "VALUES (?, ?, ?, ?, ?)",
                (message_id, *values),
            )
            return
        if tuple(existing) != values:
            msg = f"Conflicting immutable state for MessageId {message.id}."
            raise PersistenceConflictError(msg)

    def _load_messages(
        self,
        connection: sqlite3.Connection,
        conversation_id: ConversationId,
    ) -> tuple[_MessageSnapshot, ...]:
        """Load ordered messages and validate contiguous positions."""
        rows = connection.execute(
            "SELECT session_messages.position, session_messages.message_id, "
            "messages.message_id, "
            "messages.created_at, "
            "messages.content, messages.role, messages.source "
            "FROM session_messages LEFT JOIN messages "
            "ON messages.message_id = session_messages.message_id "
            "WHERE session_messages.session_id = ? "
            "ORDER BY session_messages.position",
            (str(conversation_id),),
        ).fetchall()
        for row in rows:
            if row[2] is None:
                msg = (
                    "Persisted History references a missing ConversationMessage row "
                    "for "
                    f"ConversationId {conversation_id} at position {row[0]} "
                    f"with MessageId {row[1]}."
                )
                raise PersistenceFormatError(msg)
        positions = [row[0] for row in rows]
        if positions != list(range(len(rows))):
            msg = (
                "Persisted History positions are invalid for ConversationId "
                f"{conversation_id}."
            )
            raise PersistenceFormatError(msg)
        return tuple(
            _MessageSnapshot(
                id=MessageId.parse(row[2]),
                created_at=Timestamp.from_isoformat(row[3]),
                content=row[4],
                role=ConversationMessageRole(row[5]),
                source=InteractionSource(row[6]),
            )
            for row in rows
        )

    def _load_conversations(
        self,
        connection: sqlite3.Connection,
        conversation_id: ConversationId,
    ) -> tuple[ConversationRef, ...]:
        """Load current source-keyed opaque conversation references."""
        rows = connection.execute(
            "SELECT source, value FROM conversations "
            "WHERE session_id = ? ORDER BY source",
            (str(conversation_id),),
        ).fetchall()
        return tuple(ConversationRef(InteractionSource(row[0]), row[1]) for row in rows)


def _user_tables(connection: sqlite3.Connection) -> set[str]:
    """Return ordinary user table names from one SQLite database."""
    rows = connection.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' "
        "AND name NOT LIKE 'sqlite_%'",
    ).fetchall()
    return {row[0] for row in rows}


def _validate_required_columns(connection: sqlite3.Connection) -> None:
    """Reject version-1 tables that lack essential persistence columns."""
    for table, required_columns in _REQUIRED_COLUMNS.items():
        rows = connection.execute(f"PRAGMA table_info({table})").fetchall()
        columns = {row[1] for row in rows}
        if not required_columns.issubset(columns):
            msg = f"SQLite persistence table {table} lacks required columns."
            raise PersistenceFormatError(msg)

# Copyright (c) 2026
"""Experimental Tool bridge over bounded filesystem reads."""

from __future__ import annotations

from dataclasses import dataclass
from enum import StrEnum
from typing import TYPE_CHECKING

from devtools.core.paths import resolve_path
from devtools.resources.filesystem import (
    FileFormat,
    FileFormatError,
    FilesystemNotFoundError,
    FilesystemPermissionError,
    read,
    resolve_file_format,
)
from devtools.tools.errors import ToolInputError

if TYPE_CHECKING:
    from pathlib import Path

    from devtools.core.paths import ResolvedPath
    from devtools.resources.filesystem import File


class ReadRepositoryFileTool:
    """Read bounded textual repository files within one configured root scope."""

    _NAME = "read_repository_file"
    _DESCRIPTION = "Read one bounded textual file below the configured repository root."

    def __init__(self, root: ResolvedPath) -> None:
        """Create a read-only Tool scoped to one repository root."""
        self._root = _normalize(root)

    @property
    def name(self) -> str:
        """Return the local capability label."""
        return self._NAME

    @property
    def description(self) -> str:
        """Return the provider-neutral capability description."""
        return self._DESCRIPTION

    def validate(self, arguments: ResolvedPath) -> None:
        """Reject paths outside this Tool's configured semantic scope."""
        normalized_arguments = _normalize(arguments)

        if normalized_arguments.value.is_relative_to(self._root.value):
            return

        msg = f"Path is outside the configured repository root: {arguments}."
        raise ToolInputError(msg)

    async def execute(self, arguments: ResolvedPath) -> File:
        """Read inferred structured formats or arbitrary decodable repository text."""
        path = _normalize(arguments)
        try:
            resolve_file_format(path)
        except FileFormatError:
            return read(path, file_format=FileFormat.TEXT)
        return read(path)


class RepositoryDirectoryEntryKind(StrEnum):
    """Describe the direct filesystem kind exposed by bounded directory listing."""

    FILE = "file"
    DIRECTORY = "directory"
    SYMLINK = "symlink"
    OTHER = "other"


@dataclass(frozen=True, slots=True)
class RepositoryDirectoryEntry:
    """Retain one direct repository-directory entry without a host path."""

    name: str
    kind: RepositoryDirectoryEntryKind


@dataclass(frozen=True, slots=True)
class RepositoryDirectoryListing:
    """Retain one deterministic bounded direct repository-directory listing."""

    entries: tuple[RepositoryDirectoryEntry, ...]
    truncated: bool


class ListRepositoryDirectoryTool:
    """List bounded direct entries within one configured repository-root scope."""

    _NAME = "list_repository_directory"
    _DESCRIPTION = "List bounded direct entries inside one repository directory."
    _DEFAULT_MAXIMUM_ENTRIES = 64

    def __init__(
        self,
        root: ResolvedPath,
        *,
        maximum_entries: int = _DEFAULT_MAXIMUM_ENTRIES,
    ) -> None:
        """Create one non-recursive read-only listing capability."""
        if maximum_entries <= 0:
            msg = "Maximum directory entries must be positive."
            raise ValueError(msg)
        self._root = _normalize(root)
        self._maximum_entries = maximum_entries

    @property
    def name(self) -> str:
        """Return the local capability label."""
        return self._NAME

    @property
    def description(self) -> str:
        """Return the provider-neutral capability description."""
        return self._DESCRIPTION

    def validate(self, arguments: ResolvedPath) -> None:
        """Reject paths outside this Tool's configured semantic scope."""
        normalized_arguments = _normalize(arguments)
        if normalized_arguments.value.is_relative_to(self._root.value):
            return
        msg = f"Path is outside the configured repository root: {arguments}."
        raise ToolInputError(msg)

    async def execute(self, arguments: ResolvedPath) -> RepositoryDirectoryListing:
        """Enumerate a deterministic bounded direct listing for admitted input."""
        directory = _normalize(arguments).value
        try:
            if not directory.exists():
                msg = f"Filesystem path does not exist: {arguments}."
                raise FilesystemNotFoundError(msg)
            if not directory.is_dir():
                msg = f"Filesystem path is not a directory: {arguments}."
                raise NotADirectoryError(msg)
            paths = sorted(directory.iterdir(), key=lambda entry: entry.name)
        except PermissionError as error:
            msg = f"Permission denied while listing directory: {arguments}."
            raise FilesystemPermissionError(msg) from error
        limit = self._maximum_entries
        return RepositoryDirectoryListing(
            entries=tuple(_directory_entry(path) for path in paths[:limit]),
            truncated=len(paths) > limit,
        )


def _directory_entry(path: Path) -> RepositoryDirectoryEntry:
    """Classify one direct entry without resolving or disclosing its host path."""
    if path.is_symlink():
        kind = RepositoryDirectoryEntryKind.SYMLINK
    elif path.is_file():
        kind = RepositoryDirectoryEntryKind.FILE
    elif path.is_dir():
        kind = RepositoryDirectoryEntryKind.DIRECTORY
    else:
        kind = RepositoryDirectoryEntryKind.OTHER
    return RepositoryDirectoryEntry(path.name, kind)


def _normalize(path: ResolvedPath) -> ResolvedPath:
    """Apply the repository's existing path-resolution semantics."""
    return resolve_path(path.value)

