                snapshot = _ConversationSnapshot(
                    id=conversation_id,
                    created_at=Timestamp.from_isoformat(row[0]),
                    messages=self._load_messages(connection, conversation_id),
                    conversations=self._load_conversations(connection, conversation_id),
                )
